    let rankedList;
    if (priorCand && independent) {
      const scored = scoreCandidates([researchCand, priorCand], { trust, now });
      rankedList = scored.ranked[field];
    } else if (priorCand) {
      const rScored = scoreCandidates([researchCand], { trust, now });
      const pScored = scoreCandidates([priorCand], { trust, now });
      rankedList = _sortRankedByScore([...rScored.ranked[field], ...pScored.ranked[field]], trust);
    } else {
      const rScored = scoreCandidates([researchCand], { trust, now });
      rankedList = rScored.ranked[field];
    }

    const researchEntry = rankedList.find((c) => c.source === "claude_web");
    const priorEntry = priorCand ? rankedList.find((c) => c.source === "prior_on_file") : null;

    result[field] = {
      field,
      ranked: rankedList,
      research: researchEntry,
      recency_source: (rc.recency_source_by_field && rc.recency_source_by_field[field]) || "unmatched",
      prior_on_file: priorCand ? {
        value: priorValue,
        components: priorEntry ? priorEntry.components : null,
        independent,
      } : null,
    };
  }

  return result;
}

function buildJudgeRequestBody(row, model, maxTokens) {
  const id = (row && row.identity_keys) || {};
  const existing = (row && row.existingRecord) || {};
  const rc = (row && row.research_candidate) || {};
  const data = rc.data || {};
  const scoring = (row && row.research_scoring) || {};

  const restrictedData = {};
  const restrictedScoring = {};
  for (const f of _JUDGE_DATA_FIELDS) {
    if (f in data) restrictedData[f] = data[f];
    if (f in scoring) restrictedScoring[f] = scoring[f];
  }

  const company = {
    name: id.companyName || existing.name || null,
    domain: id.domain || existing.domain || null,
    existing_lv_org_type: existing.lv_org_type || null,
    research_candidate: {
      data: restrictedData,
      evidence_by_field: rc.evidence_by_field || {},
    },
    // TA-5: grounding for the judge — every judge-eligible field's A/R/G/T composite,
    // restricted to the SAME field list restrictedData already uses, so JG-2 holds by
    // construction: no numeric firmographic value can ever appear here because no such
    // field is ever in the list.
    scoring: restrictedScoring,
    escalation_reasons: (row && row.judge_reasons) || [],
  };

  const system = [
    "You are adjudicating a company classification conflict for an ICP scoring pipeline.",
    "Adjudicate identity and classification STRICTLY from the evidence already supplied",
    "below - never re-research, never assert any fact that no cited URL in",
    "evidence_by_field supports. If there is no evidence for a claim, the decision MUST",
    "be needs_review with a null chosen value, NEVER false - a missing citation is never",
    "evidence of absence (TS-1).",
    // TA-6: label the prior honestly — it is not independent corroboration.
    "The scoring object shows how the research candidate compares to the value already",
    "on file (prior_on_file), including a recency-derived ordering term (higher means",
    "fresher evidence) - recency is ordering information ONLY and is never a reason to",
    "reject a claim, because a fact can be stable for decades without being wrong for",
    "being old. prior_on_file is NOT an independent corroborating source - it is what is",
    "already recorded, which may itself derive from an earlier unverified research pass,",
    "so agreement with it is not evidence; ground the decision in the cited URLs only.",
    "Return ONLY one JSON object (no prose, no markdown fences) with exactly these keys: " +
      JSON.stringify([...JUDGE_OUTPUT_REQUIRED, "chosen_field"]) + ".",
  ].join(" ");

  return {
    model,
    max_tokens: maxTokens || 4096,
    system,
    messages: [{
      role: "user",
      content: JSON.stringify({ task: "judge_classification_conflict", company }),
    }],
  };
}

// extractFinalJson — DUPLICATED from n8n/code/webResearch.js, not require()'d: Task 5's
// Judge Gate / Build Judge Request / Apply Judge Verdict Code nodes inline only
// escalation.generated.js + judge.js (not webResearch.js), so this file carries its own
// copy. Keep in parity by hand with webResearch.js's version if either changes — same
// regex, same fallback order.
function extractFinalJson(content) {
  const text = (Array.isArray(content) ? content : [])
    .filter((b) => b && b.type === "text")
    .map((b) => b.text)
    .join("");
  const stripped = text.trim().replace(/^```(?:json)?\s*|\s*```$/gm, "").trim();
  try {
    return JSON.parse(stripped);
  } catch (e) {
    const m = stripped.match(/\{[\s\S]*\}/);
    if (!m) throw e;
    return JSON.parse(m[0]);
  }
}

// judgeVerdictFromHttpItem(item) — mirrors researchCandidateFromHttpItem (webResearch.js)
// exactly: NEVER THROWS, whatever shape the HTTP node hands it under
// onError:"continueRegularOutput". Every failure shape (n8n execution-error item,
// missing/empty content, Anthropic HTTP-level error body, unparseable text, a verdict
// missing a JUDGE_OUTPUT_REQUIRED key) resolves to
// { decision: "needs_review", chosen_value: null, confidence: 0, reason: "<shape>" }.
// JG-3: any verdict whose confidence < JUDGE_MIN_CONFIDENCE is rewritten to
// decision: "needs_review" before returning, regardless of what the model said.
function judgeVerdictFromHttpItem(item) {
  const fallback = (reason) => ({ decision: "needs_review", chosen_value: null, confidence: 0, reason });
  try {
    if (!item || item.error || !Array.isArray(item.content)) {
      return fallback("no usable judge response (execution error / missing content)");
    }
    const parsed = extractFinalJson(item.content);
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
      return fallback("judge response was not a JSON object");
    }
    for (const key of JUDGE_OUTPUT_REQUIRED) {
      if (!(key in parsed)) return fallback(`judge verdict missing required key: ${key}`);
    }

    let verdict = { ...parsed };
    const confidence = Number(verdict.confidence);
    verdict.confidence = Number.isFinite(confidence) ? confidence : 0;
    if (!(verdict.confidence >= JUDGE_MIN_CONFIDENCE)) {
      verdict = { ...verdict, decision: "needs_review" }; // JG-3
    }
    return verdict;
  } catch (e) {
    return fallback("judge response failed to parse: " + ((e && e.message) || "unknown error"));
  }
}

// applyJudgeVerdict(researchCandidate, verdict, reasons) -> a NEW candidate. Only a
// promote/confirm verdict at confidence >= JUDGE_MIN_CONFIDENCE keeps the adjudicated
// value; there is no other path that can promote. Everything else (needs_review,
// reject, missing verdict, sub-threshold confidence) routes through applyUnadjudicated —
// the same D5 fail-safe an unadjudicated trigger uses.
function applyJudgeVerdict(researchCandidate, verdict, reasons) {
  const v = verdict || {};
  const promotes = (v.decision === "promote" || v.decision === "confirm") &&
    typeof v.confidence === "number" && v.confidence >= JUDGE_MIN_CONFIDENCE;

  if (promotes) {
    const data = { ...((researchCandidate && researchCandidate.data) || {}) };
    if (v.chosen_field && Object.prototype.hasOwnProperty.call(v, "chosen_value")) {
      data[v.chosen_field] = v.chosen_value;
    }
    return {
      ...(researchCandidate || {}),
      data,
      judge_flags: {
        ...((researchCandidate && researchCandidate.judge_flags) || {}),
        adjudicated: true,
        decision: v.decision,
      },
    };
  }

  const demoted = applyUnadjudicated(researchCandidate, reasons);
  return {
    ...demoted,
    judge_flags: {
      ...(demoted.judge_flags || {}),
      needs_review: true,
      verdict_reason: v.reason || null,
    },
  };
}

// --- n8n wrapper (companies): Judge Gate ---
// RO-2: size-band disagreement is detected downstream inside Merge Company and is
// deliberately invisible here — this gate runs before that node, so no model call can
// ever be triggered by a size disagreement alone.
const ALLOW_JUDGE_ESCALATION = true;
const MAX_JUDGE_VALIDATIONS_PER_RUN = 50;
const allowOn = String(ALLOW_JUDGE_ESCALATION).toLowerCase() === "true";
const MAX_PER_RUN = parseInt(String(MAX_JUDGE_VALIDATIONS_PER_RUN), 10);
const NOW = new Date().toISOString();

// Phase-15 provenance blob is a JSON string property that may be absent, empty, or
// malformed (truncated at the 60000-char cap, or simply never written yet) — a parse
// failure yields an empty object and must never throw (D1: without a parseable
// provenance blob, the independence guard has nothing to read and would fail OPEN).
function _parseProvenanceBlob(raw) {
  if (!raw) return {};
  try {
    const parsed = JSON.parse(raw);
    return (parsed && typeof parsed === "object" && !Array.isArray(parsed)) ? parsed : {};
  } catch (e) {
    return {};
  }
}

// Pass 1: per row, evidence sufficiency (JG-4/D6, always) + TA-1 scoring (every
// researched row, escalated or not — scoring ranks, it never decides) + escalation
// trigger detection (JG-1/RO-1/RO-2). Does not decide the cap or the fail-safe yet —
// applyCostCap (TA-7) needs the full needs_judge set up front so the kill switch and the
// budget share one code path (pass 0 when off, MAX_PER_RUN when on), rather than a
// duplicated branch.
//
// BOUNDARY THAT MUST HOLD (D2/D3): research_scoring is strictly additive to the judge's
// INPUT. It must NEVER become an alternate escalation gate — a high composite score may
// never suppress an already-fired escalation reason. computeEscalation's reasons list
// remains the SOLE gate on whether the judge is invoked; research_scoring is never read
// by it.
const gated = $input.all().map((it) => {
  const row = it.json;
  const domain = (row.identity_keys && row.identity_keys.domain) ||
                 (row.existingRecord && row.existingRecord.domain) || null;
  const researchCandidate = applyEvidenceSufficiency(row.research_candidate, domain);

  const provenance = _parseProvenanceBlob(
    row.existingRecord && row.existingRecord.lv_enrichment_provenance);
  const research_scoring = scoreResearchCandidates(
    researchCandidate, row.existingRecord || {}, provenance, { now: NOW });

  const { needsJudge, reasons } = computeEscalation(researchCandidate, row.existingRecord || {});
  return { ...row, research_candidate: researchCandidate, research_scoring,
           needs_judge: needsJudge, judge_reasons: reasons };
});

// Pass 2: applyCostCap enforces the kill switch AND the per-run budget through the same
// path — 0 when escalation is off (caps every row), MAX_PER_RUN when it is on.
const capped = applyCostCap(gated, allowOn ? MAX_PER_RUN : 0);

// Pass 3: any row that had a trigger fire (judge_reasons non-empty) but ends up here
// with needs_judge false — whether from the kill switch or the cap — runs the D5
// fail-safe, so an unadjudicated hard-veto input never reaches Merge Company. Rows that
// never had a trigger (judge_reasons empty) are already needs_judge:false and untouched.
return capped.map((row) => {
  if ((row.judge_reasons || []).length > 0 && !row.needs_judge) {
    const researchCandidate = applyUnadjudicated(row.research_candidate, row.judge_reasons);
    return { json: { ...row, research_candidate: researchCandidate } };
  }
  return { json: row };
});

