  const budget = Number.isFinite(maxPerRun) ? maxPerRun : 0;
  let remaining = budget;
  return (rows || []).map((row) => {
    if (!row || !row.needs_judge) return row;
    if (remaining <= 0) {
      return { ...row, needs_judge: false, judge_capped: true };
    }
    remaining -= 1;
    return row;
  });
